svg.script:

(function() {
  // Elements
  var tab1 = document.getElementById('a16p2-tab-1');
  var tab2 = document.getElementById('a16p2-tab-2');
  var tab3 = document.getElementById('a16p2-tab-3');
  var tab4 = document.getElementById('a16p2-tab-4');

  var btnHbNormal = document.getElementById('a16p2-btn-hb-normal');
  var btnHbAnemia = document.getElementById('a16p2-btn-hb-anemia');

  var rectNormal = document.getElementById('a16p2-rect-hb-normal');
  var rectAnemia = document.getElementById('a16p2-rect-hb-anemia');
  var iconAnemia = document.getElementById('a16p2-icon-hb-anemia');
  var textAnemia = document.getElementById('a16p2-text-hb-anemia');

  var outBox = document.getElementById('a16p2-out-box');
  var outTitle = document.getElementById('a16p2-out-title');
  var outLine1 = document.getElementById('a16p2-out-line1');
  var outLine2 = document.getElementById('a16p2-out-line2');

  var summaryStrip = document.getElementById('a16p2-summary-strip');
  var summaryTitle = document.getElementById('a16p2-summary-title');
  var summaryDesc = document.getElementById('a16p2-summary-desc');
  var summaryAlert = document.getElementById('a16p2-summary-alert');

  var badgeConduta = document.getElementById('a16p2-badge-conduta');
  var infoTit = document.getElementById('a16p2-info-tit');
  var infoDose = document.getElementById('a16p2-info-dose');
  var infoSal = document.getElementById('a16p2-info-sal');
  var infoDur1 = document.getElementById('a16p2-info-dur1');
  var infoDur2 = document.getElementById('a16p2-info-dur2');
  var infoDur3 = document.getElementById('a16p2-info-dur3');

  var flowLine = document.getElementById('a16p2-flow-line');

  // State
  var currentHb = 'normal'; // 'normal' | 'anemia'
  var currentTab = 1; // 1, 2, 3, 4

  function setTab(num) {
    currentTab = num;
    var tabs = [tab1, tab2, tab3, tab4];
    tabs.forEach(function(t, idx) {
      if (!t) return;
      var rect = t.querySelector('rect');
      var circle = t.querySelector('circle');
      var text = t.querySelector('text');
      if (idx + 1 === num) {
        rect.setAttribute('fill', 'var(--a16p2-teal-bg, rgba(20, 184, 166, 0.12))');
        rect.setAttribute('stroke', 'var(--a16p2-teal, #14b8a6)');
        rect.setAttribute('stroke-width', '1.5');
        circle.setAttribute('fill', 'var(--a16p2-teal, #14b8a6)');
        text.setAttribute('fill', 'var(--a16p2-teal, #14b8a6)');
        text.setAttribute('font-weight', '700');
      } else {
        rect.setAttribute('fill', 'var(--a16p2-card, #1e293b)');
        rect.setAttribute('stroke', 'var(--a16p2-border, #334155)');
        rect.setAttribute('stroke-width', '1');
        circle.setAttribute('fill', 'var(--a16p2-ink-muted, #94a3b8)');
        text.setAttribute('fill', 'var(--a16p2-ink-main, #f8fafc)');
        text.setAttribute('font-weight', '600');
      }
    });

    if (num === 1) {
      updateHbDisplay(currentHb);
    } else if (num === 2) {
      badgeConduta.textContent = 'PROFILAXIA';
      badgeConduta.setAttribute('fill', '#ffffff');
      infoTit.textContent = 'PROFILAXIA 2º E 3º TRIMESTRES';
      infoDose.textContent = '40 a 60 mg de Ferro Elementar / dia';
      infoSal.textContent = '(= 1 drágea de Sulfato Ferroso 200 mg/dia)';
      infoDur1.textContent = '• Início: a partir da 20ª semana de gestação.';
      infoDur2.textContent = '• Cutoff de Anemia 2ºT: Hb < 10,5 g/dL (hemodiluição).';
      infoDur3.textContent = '  (Se Hb < 10,5 g/dL no 2ºT → mudar para Reposição!)';
    } else if (num === 3) {
      badgeConduta.textContent = 'PUERPÉRIO';
      badgeConduta.setAttribute('fill', '#ffffff');
      infoTit.textContent = 'MANUTENÇÃO NO PUERPÉRIO';
      infoDose.textContent = '40 a 60 mg de Ferro Elementar / dia';
      infoSal.textContent = '(= Suplementação pós-parto de rotina)';
      infoDur1.textContent = '• Com Amamentação: Manter até o FIM DA LACTAÇÃO.';
      infoDur2.textContent = '• Sem Amamentação: Manter por 3 MESES pós-parto.';
      infoDur3.textContent = '  Garante a recomposição dos estoques maternos de ferro.';
    } else if (num === 4) {
      badgeConduta.textContent = 'REGRAS';
      badgeConduta.setAttribute('fill', '#ffffff');
      infoTit.textContent = 'BOAS PRÁTICAS DE PRESCRIÇÃO';
      infoDose.textContent = 'Vitamina C (+); Cálcio (-)';
      infoSal.textContent = '(Sulfato Ferroso 200mg sal = 40mg Fe elem)';
      infoDur1.textContent = '• Ingerir com suco cítrico (laranja/limão) em jejum.';
      infoDur2.textContent = '• NUNCA ingerir junto com leite ou derivados (cálcio).';
      infoDur3.textContent = '  Efeitos adversos GI: diarreia, constipação, epigastralgia.';
    }
  }

  function updateHbDisplay(mode) {
    currentHb = mode;
    if (mode === 'normal') {
      // Normal state (Green / Teal)
      rectNormal.setAttribute('fill', 'var(--a16p2-teal-bg, rgba(20, 184, 166, 0.12))');
      rectNormal.setAttribute('stroke', 'var(--a16p2-teal, #14b8a6)');
      rectNormal.setAttribute('stroke-width', '2');

      rectAnemia.setAttribute('fill', 'var(--a16p2-card-hi, #334155)');
      rectAnemia.setAttribute('stroke', 'var(--a16p2-border, #334155)');
      rectAnemia.setAttribute('stroke-width', '1');
      iconAnemia.setAttribute('fill', 'var(--a16p2-ink-muted, #94a3b8)');
      textAnemia.setAttribute('fill', 'var(--a16p2-ink-main, #f8fafc)');

      outBox.setAttribute('stroke', 'var(--a16p2-teal, #14b8a6)');
      outTitle.setAttribute('fill', 'var(--a16p2-teal, #14b8a6)');
      outTitle.textContent = 'DIAGNÓSTICO: 1ºT SEM ANEMIA (Hb ≥ 11,0 g/dL)';
      outLine1.textContent = '• PROFILAXIA NÃO INDICADA no 1º Trimestre. Não prescrever ferro de rotina agora.';
      outLine2.textContent = '• Próximo passo: Iniciar 40–60 mg de ferro elementar/dia a partir da 20ª semana (2ºT).';

      summaryStrip.setAttribute('fill', 'var(--a16p2-teal, #14b8a6)');
      summaryTitle.textContent = 'REGRA DE OURO DO 1º TRIMESTRE';
      summaryDesc.textContent = 'Se Hb ≥ 11,0 g/dL no 1ºT: SEM profilaxia com ferro! A profilaxia só inicia no 2ºT (40-60 mg Fe elem/d).';
      summaryAlert.textContent = 'Exceção: Se Hb < 11,0 g/dL no 1ºT → Anemia! Iniciar Reposição imediata (120–200 mg Fe elem/dia).';

      badgeConduta.textContent = 'PROFILAXIA';
      infoTit.textContent = 'PROFILAXIA UNIVERSAL (2ºT EM DIANTE)';
      infoDose.textContent = '40 a 60 mg de Ferro Elementar / dia';
      infoSal.textContent = '(= 1 drágea de Sulfato Ferroso 200 mg/dia)';
      infoDur1.textContent = '• Manter diariamente do 2º Trimestre até o parto.';
      infoDur2.textContent = '• Puerpério: Continuar durante toda a LACTAÇÃO';
      infoDur3.textContent = '  (ou por 3 meses pós-parto se não amamentar).';

      flowLine.setAttribute('stroke', 'var(--a16p2-teal, #14b8a6)');
    } else {
      // Anemia state (Red / Coral Alert)
      rectNormal.setAttribute('fill', 'var(--a16p2-card-hi, #334155)');
      rectNormal.setAttribute('stroke', 'var(--a16p2-border, #334155)');
      rectNormal.setAttribute('stroke-width', '1');

      rectAnemia.setAttribute('fill', 'var(--a16p2-coral-bg, rgba(244, 63, 94, 0.12))');
      rectAnemia.setAttribute('stroke', 'var(--a16p2-coral, #f43f5e)');
      rectAnemia.setAttribute('stroke-width', '2');
      iconAnemia.setAttribute('fill', 'var(--a16p2-coral, #f43f5e)');
      textAnemia.setAttribute('fill', 'var(--a16p2-coral, #f43f5e)');

      outBox.setAttribute('stroke', 'var(--a16p2-coral, #f43f5e)');
      outTitle.setAttribute('fill', 'var(--a16p2-coral, #f43f5e)');
      outTitle.textContent = 'ALERTA: 1ºT COM ANEMIA DETECTADA (Hb < 11,0 g/dL)';
      outLine1.textContent = '• REPOSIÇÃO IMEDIATA INDICADA! Tratar a anemia sem aguardar o 2º trimestre.';
      outLine2.textContent = '• Prescrever 120 a 200 mg de Ferro Elementar/dia (3 a 5 drágeas de Sulfato Ferroso 200 mg/d).';

      summaryStrip.setAttribute('fill', 'var(--a16p2-coral, #f43f5e)');
      summaryTitle.textContent = 'ALERTA CLÍNICO: CONDUTA DE REPOSIÇÃO NO 1ºT';
      summaryDesc.textContent = 'Hb < 11,0 g/dL no 1ºT confirma ANEMIA GESTACIONAL. Iniciar TRATAMENTO IMEDIATO!';
      summaryAlert.textContent = 'Dose de Tratamento: 120 a 200 mg de Ferro Elementar/dia (fracionado 1h antes das refeições).';

      badgeConduta.textContent = 'TRATAMENTO';
      infoTit.textContent = 'REPOSIÇÃO IMEDIATA (ANEMIA NO 1ºT)';
      infoDose.textContent = '120 a 200 mg de Ferro Elementar / dia';
      infoSal.textContent = '(= 3 a 5 drágeas de Sulfato Ferroso 200 mg/dia)';
      infoDur1.textContent = '• Iniciar IMEDIATAMENTE no 1º Trimestre.';
      infoDur2.textContent = '• Repetir Hemograma em 30–60 dias para avaliar resposta.';
      infoDur3.textContent = '  Alvo: Elevação de Hb ≥ 1 g/dL em 3 a 4 semanas de tratamento.';

      flowLine.setAttribute('stroke', 'var(--a16p2-coral, #f43f5e)');
    }
  }

  // Event Listeners
  if (tab1) tab1.addEventListener('click', function() { setTab(1); });
  if (tab2) tab2.addEventListener('click', function() { setTab(2); });
  if (tab3) tab3.addEventListener('click', function() { setTab(3); });
  if (tab4) tab4.addEventListener('click', function() { setTab(4); });

  if (btnHbNormal) btnHbNormal.addEventListener('click', function() { updateHbDisplay('normal'); });
  if (btnHbAnemia) btnHbAnemia.addEventListener('click', function() { updateHbDisplay('anemia'); });

  // Keyboard Accessibility
  [tab1, tab2, tab3, tab4, btnHbNormal, btnHbAnemia].forEach(function(el) {
    if (!el) return;
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        el.click();
      }
    });
  });

  // Init
  setTab(1);
})();
